                    if (response.SelectToken("status").ToString() == "Completed" && response.SelectToken("$.result") != null)
                    {
                        _Logger.LogInformation("[MockResponseHelper] - SubmitResponseToPartnerAPI - TransactionLoanInformation is not null - ");

