                        if (result != null)
                        {
                            _Logger.LogInformation("[MockResponseHelper] - SubmitResponseToPartnerAPI - Before Getting epcResponse from Payload. ");

                            // Gettting dynamic response from Payload. 

                            if(_IntegrationType == "Appraisal")
