﻿<!DOCTYPE html>
<html lang="en" xmlns="http://www.w3.org/1999/xhtml">
<head>

    <meta charset="utf-8" />
    <meta http-equiv="X-UA-Compatible" content="IE=edge" />
    <title>Test Appraisal Company</title>
    <link href="lib/css/bootstrap.min.css" rel="stylesheet">
    <!-- Include Bootstrap Datepicker -->
    <link rel="stylesheet" href="lib/css/datepicker.min.css" />
    <link rel="stylesheet" href="lib/css/datepicker3.min.css" />
    <style type="text/css">
        /* Start by setting display:none to make this hidden.
        Then we position it in relation to the viewport window
        with position:fixed. Width, height, top and left speak
        speak for themselves. Background we set to 80% white with
        our animation centered, and no-repeating */
        .modal {
            display: none;
            position: fixed;
            z-index: 1500 !important;
            top: 0;
            left: 0;
            height: 100%;
            width: 100%;
            background: rgba( 30, 30, 30, .5 );
        }

        /* When the body has the loading class, we turn
        the scrollbar off with overflow:hidden */
        body.loading {
            overflow: hidden;
        }

            /* Anytime the body has the loading class, our
        modal element will be visible */
            body.loading .modal {
                display: block;
            }

        .form-label {
            padding: 3px;
        }

        .form-control {
            margin-bottom: 2px !important;
        }

        .modal-header {
            background: #eff4f9;
            border-top-left-radius: 5px;
            border-top-right-radius: 5px;
        }

        .modal-success-header {
            background: #18bebc;
            color: white;
        }

        .modal-error-header {
            background: #e74c3c;
            color: white;
        }

        .modal {
            text-align: center;
            padding: 0 !important;
        }

            .modal:before {
                content: '';
                display: inline-block;
                height: 100%;
                vertical-align: middle;
                margin-right: -4px;
            }

        .modal-dialog {
            display: inline-block;
            text-align: left;
            vertical-align: middle;
        }

        .radio-inline {
            vertical-align: middle;
        }

        .thead-default {
            background-color: #eff4f9;
        }

        .tab-content {
            border: 1px solid #ecf0f1;
            border-top: none;
            padding: 5px;
        }

        .nav-tabs {
            margin-bottom: 0;
        }

        .tab-content > .tab-pane {
            visibility: hidden;
            padding: 5px;
        }

        .tab-content > .active {
            visibility: visible;
        }

        .radiolist {
            padding: 3px;
        }

        .selected {
            background-color: #fbe8b4;
        }

        .btn-file {
            position: relative;
            overflow: hidden;
        }

            .btn-file input[type=file] {
                position: absolute;
                top: 0;
                right: 0;
                min-width: 100%;
                min-height: 100%;
                font-size: 100px;
                text-align: right;
                filter: alpha(opacity=0);
                opacity: 0;
                outline: none;
                background: white;
                cursor: inherit;
                display: block;
            }

        .date-picker {
            padding: 0px;
        }

        .order-row {
            cursor: pointer;
        }

        .pending {
            padding: 2px;
            background-color: #eb6759;
            color: white;
            border-radius: 3px;
            font-size: 13px;
            text-align: center;
        }

        .completed {
            padding: 2px;
            background-color: #8abc82;
            color: white;
            border-radius: 3px;
            font-size: 13px;
            text-align: center;
        }

        .otherstatus {
            padding: 2px;
            background-color: #dab478;
            color: white;
            border-radius: 3px;
            font-size: 13px;
            text-align: center;
        }

        .modal-header > h3 {
            font-size: 18px;
        }

        .panel-heading .accordion-toggle:after {
            /* symbol for "opening" panels */
            font-family: 'Glyphicons Halflings'; /* essential for enabling glyphicon */
            content: "\e114"; /* adjust as needed, taken from bootstrap.css */
            float: right; /* adjust as needed */
            color: grey; /* adjust as needed */
        }

        .panel-heading .accordion-toggle.collapsed:after {
            /* symbol for "collapsed" panels */
            content: "\e080"; /* adjust as needed, taken from bootstrap.css */
        }
    </style>
</head>
<body>

    <!-- Add Attachments Modal -->
    <div id="addAttachmentsModal" class="modal fade" role="dialog" data-backdrop="static" data-keyboard="false">
        <div class="modal-dialog">
            <div class="modal-content">
                <div class="modal-header panel-default">
                    <button type="button" class="close" data-dismiss="modal" aria-hidden="true">&times;</button>
                    <h4 class="modal-title">Attachment List</h4>
                </div>
                <div class="modal-body">
                    <div class="row">
                        <div class="col-md-12" style="text-align: right; padding-bottom: 4px;">
                            <button type="button" class="btn btn-default btn-sm">Attach</button>
                        </div>
                    </div>
                    <table class="table table-hover table-bordered">
                        <thead class="thead-default">
                            <tr>
